import { proxyActivities, type ActivityOptions } from "@temporalio/workflow";
import type * as activities from "./activities";

// Calls to Jira, Slack, GitHub and AWS: one attempt may take up to 5 minutes.
export const SHORT: ActivityOptions = { startToCloseTimeout: "5 minutes" };

// Anything that follows a VM: a far safety net, plus a heartbeat that notices a dead worker.
export const LONG: ActivityOptions = { startToCloseTimeout: "7 days", heartbeatTimeout: "2 minutes" };

export const act = proxyActivities<typeof activities>(LONG);
export const peopleApis = proxyActivities<typeof activities>(SHORT);

const NEVER_RETRY = ["ScopeDenied", "PlanRejected", "NeedsPerson", "StoppedByPerson"];

export const AWS: RetryPolicy = { initialInterval: "1s", backoffCoefficient: 2, maximumInterval: "1 minute",
  maximumAttempts: 10, nonRetryableErrorTypes: NEVER_RETRY };
export const PEOPLE_APIS: RetryPolicy = { initialInterval: "5s", backoffCoefficient: 2, maximumInterval: "5 minutes",
  nonRetryableErrorTypes: NEVER_RETRY }; // no attempt limit

export const act = proxyActivities<typeof activities>({ ...LONG, retry: AWS });
export const peopleApis = proxyActivities<typeof activities>({ ...SHORT, retry: PEOPLE_APIS });

import { activityInfo, heartbeat } from "@temporalio/activity";

export async function build(ticket: string): Promise<string> {
  const { attempt, heartbeatDetails } = activityInfo();
  const done: number = heartbeatDetails ?? 0;
  console.log(`attempt ${attempt}: building ${ticket}, starting after step ${done}`);
  for (let step = done + 1; step <= 20; step++) {
    await new Promise((resolve) => setTimeout(resolve, 1000)); // one second of work
    console.log(`  step ${step} done`);
    heartbeat(step);
  }
  return `built ${ticket} in 20 steps`;
}

import { ApplicationFailure, heartbeat } from "@temporalio/activity";
import { setTimeout as sleep } from "node:timers/promises";

export const workInSandbox = async (vm: Sandbox, task: Task): Promise<RunOutcome> => {
  await ensureHarnessRunning(vm, task); // starts Nova only if it is not running yet
  for (;;) {
    const beat = await brokerInternal.get<Heartbeat>(`/internal/runs/${task.runId}/heartbeat`);
    heartbeat({ step: beat.step, progress: beat.progress }); // to Temporal: this attempt is alive
    if (["done", "needs_answer", "preempted", "failed"].includes(beat.state)) return toOutcome(beat);
    if (beat.age_s > 300) throw ApplicationFailure.create({ type: "SandboxDead", nonRetryable: true });
    await sleep(30_000);
  }
};

