// activities.mjs: a second long activity that heartbeats its progress
export const runChecks = async (ticket) => {
  const { attempt, heartbeatDetails } = activityInfo();
  const passed = heartbeatDetails ?? 0;
  console.log(`attempt ${attempt}: checking ${ticket}, starting after check ${passed}`);
  for (let check = passed + 1; check <= 10; check++) {
    await new Promise((resolve) => setTimeout(resolve, 1000));
    console.log(`  check ${check} passed`);
    heartbeat(check);
  }
  return `${ticket}: 10 of 10 checks passed`;
};

// workflows.mjs
const { build, runChecks } = proxyActivities({ startToCloseTimeout: '7 days', heartbeatTimeout: '5 seconds' });

export async function ticketToPr(ticket) {
  const built = await build(ticket);
  const checked = await runChecks(ticket);
  return `${built}; ${checked}`;
}
